void DiffusionPlanner::on_timer()
{
  // Timer callback function
  autoware_utils_debug::ScopedTimeTrack st(__func__, *time_keeper_);

  diagnostics_inference_->clear();

  const rclcpp::Time current_time(get_clock()->now());
  if (!core_->is_model_loaded()) {
    RCLCPP_WARN_THROTTLE(
      get_logger(), *this->get_clock(), constants::LOG_THROTTLE_INTERVAL_MS,
      "Model not loaded. Inference is disabled. Check onnx_model_path and args_path parameters.");
    diagnostics_inference_->update_level_and_message(DiagnosticStatus::ERROR, "Model not loaded");
    diagnostics_inference_->publish(current_time);
    return;
  }

  if (!core_->is_map_loaded()) {
    RCLCPP_INFO_THROTTLE(
      get_logger(), *this->get_clock(), constants::LOG_THROTTLE_INTERVAL_MS,
      "Waiting for map data...");
    diagnostics_inference_->update_level_and_message(DiagnosticStatus::WARN, "Map data not loaded");
    diagnostics_inference_->publish(current_time);
    return;
  }

  // Take data from subscribers
  auto objects = sub_tracked_objects_.take_data();
  auto ego_kinematic_state = sub_current_odometry_.take_data();
  auto ego_acceleration = sub_current_acceleration_.take_data();
  auto traffic_signals = sub_traffic_signals_.take_data();
  auto temp_route_ptr = route_subscriber_.take_data();
  auto turn_indicators_ptr = sub_turn_indicators_.take_data();

  // Prepare frame context using core
  const std::optional<FrameContext> frame_context = core_->create_frame_context(
    ego_kinematic_state, ego_acceleration, objects, traffic_signals, turn_indicators_ptr,
    temp_route_ptr, this->now());

  if (!frame_context) {
    // Log detailed information about missing inputs
    RCLCPP_WARN_STREAM_THROTTLE(
      get_logger(), *this->get_clock(), constants::LOG_THROTTLE_INTERVAL_MS,
      "There is no input data. objects: "
        << (objects ? "true" : "false")
        << ", ego_kinematic_state: " << (ego_kinematic_state ? "true" : "false")
        << ", ego_acceleration: " << (ego_acceleration ? "true" : "false")
        << ", route: " << (core_->get_route() ? "true" : "false")
        << ", turn_indicators: " << (turn_indicators_ptr ? "true" : "false"));
    diagnostics_inference_->update_level_and_message(
      DiagnosticStatus::WARN, "No input data available for inference");
    diagnostics_inference_->publish(current_time);
    return;
  }

  if (traffic_signals.empty()) {
    RCLCPP_WARN_THROTTLE(
      this->get_logger(), *this->get_clock(), constants::LOG_THROTTLE_INTERVAL_MS,
      "no traffic signal received. traffic light info will not be updated");
  }

  const rclcpp::Time frame_time(frame_context->frame_time);
  InputDataMap input_data_map = core_->create_input_data(*frame_context);

  publish_debug_markers(input_data_map, frame_context->ego_to_map_transform, frame_time);

  publish_first_traffic_light_on_route(*frame_context);

  // Calculate and record metrics for diagnostics using core
  diagnostics_inference_->add_key_value(
    "valid_lane_count", core_->count_valid_elements(input_data_map, "lanes"));
  diagnostics_inference_->add_key_value(
    "valid_route_count", core_->count_valid_elements(input_data_map, "route_lanes"));
  diagnostics_inference_->add_key_value(
    "valid_polygon_count", core_->count_valid_elements(input_data_map, "polygons"));
  diagnostics_inference_->add_key_value(
    "valid_line_string_count", core_->count_valid_elements(input_data_map, "line_strings"));
  diagnostics_inference_->add_key_value(
    "valid_neighbor_count", core_->count_valid_elements(input_data_map, "neighbor_agents_past"));

  // normalization of data
  preprocess::normalize_input_data(input_data_map, core_->get_normalization_map());
  if (!utils::check_input_map(input_data_map)) {
    RCLCPP_WARN_THROTTLE(
      get_logger(), *this->get_clock(), constants::LOG_THROTTLE_INTERVAL_MS,
      "Input data contains invalid values");
    diagnostics_inference_->update_level_and_message(
      DiagnosticStatus::WARN, "Input data contains invalid values");
    diagnostics_inference_->publish(current_time);
    return;
  }

  // Run inference using core
  const auto inference_result = core_->run_inference(input_data_map);
  if (!inference_result.outputs) {
    RCLCPP_WARN_STREAM_THROTTLE(
      get_logger(), *this->get_clock(), constants::LOG_THROTTLE_INTERVAL_MS,
      "Inference failed: " << inference_result.error_msg);
    diagnostics_inference_->update_level_and_message(
      DiagnosticStatus::ERROR, inference_result.error_msg);
    diagnostics_inference_->publish(frame_time);
    return;
  }
  const auto & [predictions, turn_indicator_logit] = inference_result.outputs.value();

  PlannerOutput planner_output;
  try {
    planner_output = core_->create_planner_output(
      predictions, turn_indicator_logit, *frame_context, frame_time, generator_uuid_);
  } catch (const std::exception & e) {
    RCLCPP_ERROR_STREAM(get_logger(), "Postprocessing failed: " << e.what());
    diagnostics_inference_->update_level_and_message(DiagnosticStatus::ERROR, e.what());
    diagnostics_inference_->publish(frame_time);
    return;
  }

  pub_trajectory_->publish(planner_output.trajectory);
  pub_trajectories_->publish(planner_output.candidate_trajectories);
  pub_objects_->publish(planner_output.predicted_objects);
  pub_turn_indicators_->publish(planner_output.turn_indicator_command);

  publish_planning_factor(planner_output.trajectory);

  // Publish diagnostics
  diagnostics_inference_->publish(frame_time);
}

std::optional<FrameContext> DiffusionPlannerCore::create_frame_context(
  const std::shared_ptr<const Odometry> & ego_kinematic_state,
  const std::shared_ptr<const AccelWithCovarianceStamped> & ego_acceleration,
  const std::shared_ptr<const TrackedObjects> & objects,
  const std::vector<std::shared_ptr<const autoware_perception_msgs::msg::TrafficLightGroupArray>> &
    traffic_signals,
  const std::shared_ptr<const TurnIndicatorsReport> & turn_indicators,
  const LaneletRoute::ConstSharedPtr & route_ptr, const rclcpp::Time & current_time)
{
  route_ptr_ = (!route_ptr_ || route_ptr) ? route_ptr : route_ptr_;

  TrackedObjects empty_object_list;
  auto effective_objects = objects;

  if (params_.ignore_neighbors) {
    effective_objects = std::make_shared<TrackedObjects>(empty_object_list);
  }

  if (!effective_objects || !ego_kinematic_state || !ego_acceleration || !turn_indicators) {
    return std::nullopt;
  }

  if (!route_ptr_) {
    return std::nullopt;
  }

  Odometry kinematic_state = *ego_kinematic_state;
  if (params_.shift_x) {
    kinematic_state.pose.pose =
      utils::shift_x(kinematic_state.pose.pose, vehicle_spec_.base_link_to_center);
  }

  // Get transforms
  const geometry_msgs::msg::Pose & pose_base_link = kinematic_state.pose.pose;
  const Eigen::Matrix4d ego_to_map_transform = utils::pose_to_matrix4d(pose_base_link);
  const Eigen::Matrix4d map_to_ego_transform = utils::inverse(ego_to_map_transform);

  // Update ego history
  ego_history_.push_back(kinematic_state);
  if (ego_history_.size() > static_cast<size_t>(EGO_HISTORY_SHAPE[1])) {
    ego_history_.pop_front();
  }

  // Update turn indicators history
  turn_indicators_history_.push_back(*turn_indicators);
  if (turn_indicators_history_.size() > static_cast<size_t>(TURN_INDICATORS_SHAPE[1])) {
    turn_indicators_history_.pop_front();
  }

  // Update neighbor agent data
  agent_data_.update_histories(*effective_objects, params_.ignore_unknown_neighbors);
  const auto processed_neighbor_histories =
    agent_data_.transformed_and_trimmed_histories(map_to_ego_transform, NEIGHBOR_SHAPE[1]);

  // Update traffic light map
  const auto & traffic_light_msg_timeout_s = params_.traffic_light_group_msg_timeout_seconds;
  preprocess::process_traffic_signals(
    traffic_signals, traffic_light_id_map_, current_time, traffic_light_msg_timeout_s);

  // Create frame context
  const rclcpp::Time frame_time(ego_kinematic_state->header.stamp);
  const FrameContext frame_context{
    *ego_kinematic_state, *ego_acceleration, ego_to_map_transform, processed_neighbor_histories,
    frame_time};

  return frame_context;
}

geometry_msgs::msg::Pose shift_x(const geometry_msgs::msg::Pose & pose, const double shift_length)
{
  // Rotation matrix (3x3)
  Eigen::Matrix3d R = quaternion_to_matrix(pose.orientation);

  // Shift along the x-axis in the local frame
  Eigen::Vector3d shift_local(shift_length, 0.0, 0.0);

  // Transform shift to the global frame
  Eigen::Vector3d shift_global = R * shift_local;

  // Create new pose
  geometry_msgs::msg::Pose shifted_pose = pose;
  shifted_pose.position.x += shift_global.x();
  shifted_pose.position.y += shift_global.y();
  shifted_pose.position.z += shift_global.z();

  return shifted_pose;
}

Eigen::Matrix3d quaternion_to_matrix(const geometry_msgs::msg::Quaternion & q_msg)
{
  const double norm =
    std::sqrt(square(q_msg.w) + square(q_msg.x) + square(q_msg.y) + square(q_msg.z));
  constexpr double kEpsilon = 1e-6;
  if (norm < kEpsilon) {
    throw std::runtime_error("Quaternion norm is too small");
  }

  return Eigen::Quaterniond(q_msg.w, q_msg.x, q_msg.y, q_msg.z).toRotationMatrix();
}

Eigen::Matrix4d pose_to_matrix4d(const geometry_msgs::msg::Pose & pose)
{
  // Extract position
  double x = pose.position.x;
  double y = pose.position.y;
  double z = pose.position.z;

  // Rotation matrix (3x3)
  Eigen::Matrix3d R = quaternion_to_matrix(pose.orientation);

  // Translation vector
  Eigen::Vector3d t(x, y, z);

  // Create 4x4 transformation matrix
  Eigen::Matrix4d pose_matrix = Eigen::Matrix4d::Identity();
  pose_matrix.block<3, 3>(0, 0) = R;
  pose_matrix.block<3, 1>(0, 3) = t;

  return pose_matrix;
}

Eigen::Matrix3d quaternion_to_matrix(const geometry_msgs::msg::Quaternion & q_msg)
{
  const double norm =
    std::sqrt(square(q_msg.w) + square(q_msg.x) + square(q_msg.y) + square(q_msg.z));
  constexpr double kEpsilon = 1e-6;
  if (norm < kEpsilon) {
    throw std::runtime_error("Quaternion norm is too small");
  }

  return Eigen::Quaterniond(q_msg.w, q_msg.x, q_msg.y, q_msg.z).toRotationMatrix();
}

void AgentData::update_histories(const TrackedObjects & objects, const bool ignore_unknown_agents)
{
  const rclcpp::Time objects_timestamp(objects.header.stamp);
  std::vector<std::string> found_ids;
  for (const TrackedObject & object : objects.objects) {
    if (ignore_unknown_agents && is_unknown_object(object)) {
      continue;
    }
    const std::string object_id = autoware_utils_uuid::to_hex_string(object.object_id);
    auto it = histories_map_.find(object_id);
    if (it != histories_map_.end()) {
      it->second.update(object, objects_timestamp);
    } else {
      histories_map_.emplace(object_id, AgentHistory(INPUT_T_WITH_CURRENT));
      histories_map_.at(object_id).fill(AgentState(object, objects_timestamp));
    }
    found_ids.push_back(object_id);
  }
  // Remove histories that are not found in the current objects
  for (auto it = histories_map_.begin(); it != histories_map_.end();) {
    if (std::find(found_ids.begin(), found_ids.end(), it->first) == found_ids.end()) {
      it = histories_map_.erase(it);
    } else {
      ++it;
    }
  }
}

bool is_unknown_object(const TrackedObject & object)
{
  const auto autoware_label =
    autoware::object_recognition_utils::getHighestProbLabel(object.classification);
  return autoware_label == autoware_perception_msgs::msg::ObjectClassification::UNKNOWN;
}

inline std::uint8_t getHighestProbLabel(
  const std::vector<ObjectClassification> & object_classifications)
{
  return getHighestProbClassification(object_classifications).label;
}

inline ObjectClassification getHighestProbClassification(
  const std::vector<ObjectClassification> & object_classifications)
{
  if (object_classifications.empty()) {
    return ObjectClassification{};
  }
  return *std::max_element(
    std::begin(object_classifications), std::end(object_classifications),
    [](const auto & a, const auto & b) { return a.probability < b.probability; });
}

inline std::string to_hex_string(const unique_identifier_msgs::msg::UUID & id)
{
  std::stringstream ss;
  for (auto i = 0; i < 16; ++i) {
    ss << std::hex << std::setfill('0') << std::setw(2) << +id.uuid[i];
  }
  return ss.str();
}

void update(const TrackedObject & object, const rclcpp::Time & timestamp)
{
  AgentState state(object, timestamp);
  if (
    queue_.size() > 0 &&
    queue_.back().object_id != autoware_utils_uuid::to_hex_string(object.object_id)) {
    throw std::runtime_error("Object ID mismatch");
  }
  push_back(state);
}

inline std::string to_hex_string(const unique_identifier_msgs::msg::UUID & id)
{
  std::stringstream ss;
  for (auto i = 0; i < 16; ++i) {
    ss << std::hex << std::setfill('0') << std::setw(2) << +id.uuid[i];
  }
  return ss.str();
}

void push_back(const AgentState & state)
{
  if (full()) {
    queue_.pop_front();
  }
  queue_.push_back(state);
}

std::vector<AgentHistory> AgentData::transformed_and_trimmed_histories(
  const Eigen::Matrix4d & transform, size_t max_num_agent) const
{
  std::vector<AgentHistory> histories;
  histories.reserve(histories_map_.size());
  for (const auto & [_, history] : histories_map_) {
    histories.push_back(history);
  }
  for (auto & history : histories) {
    history.apply_transform(transform);
  }

  std::sort(histories.begin(), histories.end(), [](const AgentHistory & a, const AgentHistory & b) {
    const double a_dist =
      std::hypot(a.get_latest_state().pose(0, 3), a.get_latest_state().pose(1, 3));
    const double b_dist =
      std::hypot(b.get_latest_state().pose(0, 3), b.get_latest_state().pose(1, 3));
    return a_dist < b_dist;
  });
  if (histories.size() > max_num_agent) {
    histories.erase(
      histories.begin() + static_cast<std::ptrdiff_t>(max_num_agent), histories.end());
  }
  return histories;
}

void apply_transform(const Eigen::Matrix4d & transform)
{
  for (auto & state : queue_) {
    state.pose = transform * state.pose;
  }
}

void process_traffic_signals(
  const std::vector<autoware_perception_msgs::msg::TrafficLightGroupArray::ConstSharedPtr> & msgs,
  std::map<lanelet::Id, TrafficSignalStamped> & traffic_signal_id_map,
  const rclcpp::Time & current_time, const double time_threshold_seconds)
{
  // Update traffic signals with the latest information
  for (const auto & msg : msgs) {
    const rclcpp::Time msg_time = msg->stamp;
    for (const auto & signal : msg->traffic_light_groups) {
      auto & curr = traffic_signal_id_map[signal.traffic_light_group_id];
      if (msg_time > rclcpp::Time(curr.stamp)) {
        curr.signal = signal;
        curr.stamp = msg_time;
      }
    }
  }

  // Remove outdated traffic signals
  auto itr = traffic_signal_id_map.begin();
  while (itr != traffic_signal_id_map.end()) {
    rclcpp::Time signal_time = itr->second.stamp;
    const double age = (current_time - signal_time).seconds();
    if (age > time_threshold_seconds) {
      itr = traffic_signal_id_map.erase(itr);
    } else {
      ++itr;
    }
  }
}

InputDataMap DiffusionPlannerCore::create_input_data(const FrameContext & frame_context)
{
  InputDataMap input_data_map;

  const geometry_msgs::msg::Pose & pose_center =
    params_.shift_x
      ? utils::shift_x(
          frame_context.ego_kinematic_state.pose.pose, vehicle_spec_.base_link_to_center)
      : frame_context.ego_kinematic_state.pose.pose;
  const Eigen::Matrix4d ego_to_map_transform = utils::pose_to_matrix4d(pose_center);
  const Eigen::Matrix4d map_to_ego_transform = utils::inverse(ego_to_map_transform);
  const auto & center_x = static_cast<float>(pose_center.position.x);
  const auto & center_y = static_cast<float>(pose_center.position.y);
  const auto & center_z = static_cast<float>(pose_center.position.z);

  // random sample trajectories
  int64_t delay_step = 0;
  {
    const int64_t copy_steps = std::clamp<int64_t>(params_.delay_step, 0, OUTPUT_T / 2);
    const bool has_previous_output = !last_agent_poses_map_.empty();

    for (int64_t b = 0; b < params_.batch_size; b++) {
      std::vector<float> sampled_trajectories =
        preprocess::create_sampled_trajectories(params_.temperature_list[b]);

      if (has_previous_output) {
        constexpr int64_t agent_idx = 0;
        delay_step = copy_steps;
        for (int64_t t = 0; t <= copy_steps; ++t) {
          const size_t dst_base = agent_idx * (OUTPUT_T + 1) * POSE_DIM + (t)*POSE_DIM;
          const Eigen::Matrix4d pose_ego =
            map_to_ego_transform * last_agent_poses_map_[b][agent_idx][t];
          const float shifted_x = static_cast<float>(pose_ego(0, 3));
          const float shifted_y = static_cast<float>(pose_ego(1, 3));
          const auto [shifted_cos, shifted_sin] =
            utils::rotation_matrix_to_cos_sin(pose_ego.block<3, 3>(0, 0));

          sampled_trajectories[dst_base + 0] = (shifted_x - 10.0f) / 20.0f;
          sampled_trajectories[dst_base + 1] = shifted_y / 20.0f;
          sampled_trajectories[dst_base + 2] = shifted_cos;
          sampled_trajectories[dst_base + 3] = shifted_sin;
        }
      }

      input_data_map["sampled_trajectories"].insert(
        input_data_map["sampled_trajectories"].end(), sampled_trajectories.begin(),
        sampled_trajectories.end());
    }
  }

  // Ego history
  {
    const std::optional<rclcpp::Time> reference_time =
      params_.use_time_interpolation ? std::make_optional(frame_context.frame_time) : std::nullopt;
    const std::vector<float> single_ego_agent_past = preprocess::create_ego_agent_past(
      ego_history_, EGO_HISTORY_SHAPE[1], map_to_ego_transform, reference_time);
    input_data_map["ego_agent_past"] =
      utils::replicate_for_batch(single_ego_agent_past, params_.batch_size);
  }
  // Ego state
  {
    const auto ego_current_state = preprocess::create_ego_current_state(
      frame_context.ego_kinematic_state, frame_context.ego_acceleration,
      static_cast<float>(vehicle_spec_.wheel_base));
    input_data_map["ego_current_state"] =
      utils::replicate_for_batch(ego_current_state, params_.batch_size);
  }
  // Agent data on ego reference frame
  {
    const auto neighbor_agents_past = flatten_histories_to_vector(
      frame_context.ego_centric_neighbor_histories, MAX_NUM_NEIGHBORS, INPUT_T + 1);
    input_data_map["neighbor_agents_past"] =
      utils::replicate_for_batch(neighbor_agents_past, params_.batch_size);
  }
  // Static objects
  // TODO(Daniel): add static objects
  {
    std::vector<int64_t> single_batch_shape(
      STATIC_OBJECTS_SHAPE.begin() + 1, STATIC_OBJECTS_SHAPE.end());
    auto static_objects_data = utils::create_float_data(single_batch_shape, 0.0f);
    input_data_map["static_objects"] =
      utils::replicate_for_batch(static_objects_data, params_.batch_size);
  }

  // map data on ego reference frame
  {
    const std::vector<int64_t> segment_indices = lane_segment_context_->select_lane_segment_indices(
      map_to_ego_transform, center_x, center_y, NUM_SEGMENTS_IN_LANE);
    const auto [lanes, lanes_speed_limit] = lane_segment_context_->create_tensor_data_from_indices(
      map_to_ego_transform, traffic_light_id_map_, segment_indices, NUM_SEGMENTS_IN_LANE);
    input_data_map["lanes"] = utils::replicate_for_batch(lanes, params_.batch_size);
    input_data_map["lanes_speed_limit"] =
      utils::replicate_for_batch(lanes_speed_limit, params_.batch_size);
  }

  // route data on ego reference frame
  {
    const std::vector<int64_t> segment_indices =
      lane_segment_context_->select_route_segment_indices(
        *route_ptr_, center_x, center_y, center_z, NUM_SEGMENTS_IN_ROUTE);
    const auto [route_lanes, route_lanes_speed_limit] =
      lane_segment_context_->create_tensor_data_from_indices(
        map_to_ego_transform, traffic_light_id_map_, segment_indices, NUM_SEGMENTS_IN_ROUTE);
    input_data_map["route_lanes"] = utils::replicate_for_batch(route_lanes, params_.batch_size);
    input_data_map["route_lanes_speed_limit"] =
      utils::replicate_for_batch(route_lanes_speed_limit, params_.batch_size);
  }

  // polygons
  {
    const auto & polygons =
      lane_segment_context_->create_polygon_tensor(map_to_ego_transform, center_x, center_y);
    input_data_map["polygons"] = utils::replicate_for_batch(polygons, params_.batch_size);
  }

  // line strings
  {
    const auto & line_strings =
      lane_segment_context_->create_line_string_tensor(map_to_ego_transform, center_x, center_y);
    input_data_map["line_strings"] = utils::replicate_for_batch(line_strings, params_.batch_size);
  }

  // goal pose
  {
    const auto & goal_pose = route_ptr_->goal_pose;

    // Convert goal pose to 4x4 transformation matrix
    const Eigen::Matrix4d goal_pose_map_4x4 = utils::pose_to_matrix4d(goal_pose);

    // Transform to ego frame
    const Eigen::Matrix4d goal_pose_ego_4x4 = map_to_ego_transform * goal_pose_map_4x4;

    // Extract relative position
    const float x = goal_pose_ego_4x4(0, 3);
    const float y = goal_pose_ego_4x4(1, 3);

    // Extract heading as cos/sin from rotation matrix
    const auto [cos_yaw, sin_yaw] =
      utils::rotation_matrix_to_cos_sin(goal_pose_ego_4x4.block<3, 3>(0, 0));

    std::vector<float> single_goal_pose = {x, y, cos_yaw, sin_yaw};
    input_data_map["goal_pose"] = utils::replicate_for_batch(single_goal_pose, params_.batch_size);
  }

  // ego shape
  {
    const std::vector<float> single_ego_shape = {
      static_cast<float>(vehicle_spec_.wheel_base),
      static_cast<float>(vehicle_spec_.vehicle_length),
      static_cast<float>(vehicle_spec_.vehicle_width)};
    input_data_map["ego_shape"] = utils::replicate_for_batch(single_ego_shape, params_.batch_size);
  }

  // turn indicators
  {
    // copy from back to front, and use the front value for padding if not enough history
    std::vector<float> single_turn_indicators(INPUT_T + 1, 0.0f);
    for (int64_t t = 0; t < INPUT_T + 1; ++t) {
      const int64_t index = std::max(
        static_cast<int64_t>(turn_indicators_history_.size()) - 1 - t, static_cast<int64_t>(0));
      single_turn_indicators[INPUT_T - t] = turn_indicators_history_[index].report;
    }
    input_data_map["turn_indicators"] =
      utils::replicate_for_batch(single_turn_indicators, params_.batch_size);
  }

  // control delay
  {
    const std::vector<float> single_delay = {static_cast<float>(delay_step)};
    input_data_map["delay"] = utils::replicate_for_batch(single_delay, params_.batch_size);
  }

  return input_data_map;
}

Eigen::Matrix4d pose_to_matrix4d(const geometry_msgs::msg::Pose & pose)
{
  // Extract position
  double x = pose.position.x;
  double y = pose.position.y;
  double z = pose.position.z;

  // Rotation matrix (3x3)
  Eigen::Matrix3d R = quaternion_to_matrix(pose.orientation);

  // Translation vector
  Eigen::Vector3d t(x, y, z);

  // Create 4x4 transformation matrix
  Eigen::Matrix4d pose_matrix = Eigen::Matrix4d::Identity();
  pose_matrix.block<3, 3>(0, 0) = R;
  pose_matrix.block<3, 1>(0, 3) = t;

  return pose_matrix;
}

Eigen::Matrix3d quaternion_to_matrix(const geometry_msgs::msg::Quaternion & q_msg)
{
  const double norm =
    std::sqrt(square(q_msg.w) + square(q_msg.x) + square(q_msg.y) + square(q_msg.z));
  constexpr double kEpsilon = 1e-6;
  if (norm < kEpsilon) {
    throw std::runtime_error("Quaternion norm is too small");
  }

  return Eigen::Quaterniond(q_msg.w, q_msg.x, q_msg.y, q_msg.z).toRotationMatrix();
}

std::vector<float> create_sampled_trajectories(const double temperature)
{
  std::random_device rd;
  std::mt19937 gen(rd());
  std::normal_distribution<float> dist(0.0f, 1.0f);
  std::vector<float> sampled_trajectories((MAX_NUM_NEIGHBORS + 1) * (OUTPUT_T + 1) * POSE_DIM);
  for (float & val : sampled_trajectories) {
    val = dist(gen) * static_cast<float>(temperature);
  }
  return sampled_trajectories;
}

std::vector<float> create_ego_agent_past(
  const std::deque<nav_msgs::msg::Odometry> & odom_msgs, size_t num_timesteps,
  const Eigen::Matrix4d & map_to_ego_transform, const std::optional<rclcpp::Time> & reference_time)
{
  const size_t features_per_timestep = 4;  // x, y, cos, sin
  const size_t total_size = num_timesteps * features_per_timestep;

  std::vector<float> ego_agent_past(total_size, 0.0f);

  // Initialize cos values to 1.0 (identity heading)
  for (size_t t = 0; t < num_timesteps; ++t) {
    ego_agent_past[t * features_per_timestep + EGO_AGENT_PAST_IDX_COS] = 1.0f;
  }

  // If no odometry messages are available, return the default-initialized ego_agent_past
  if (odom_msgs.empty()) {
    return ego_agent_past;
  }

  // Lambda to transform a pose to ego frame and store into the flat array
  auto store_pose = [&](size_t timestep_idx, const geometry_msgs::msg::Pose & pose) {
    const Eigen::Matrix4d pose_map_4x4 = utils::pose_to_matrix4d(pose);
    const Eigen::Matrix4d pose_ego_4x4 = map_to_ego_transform * pose_map_4x4;
    const auto [cos_yaw, sin_yaw] =
      utils::rotation_matrix_to_cos_sin(pose_ego_4x4.block<3, 3>(0, 0));
    const size_t base_idx = timestep_idx * features_per_timestep;
    ego_agent_past[base_idx + EGO_AGENT_PAST_IDX_X] = pose_ego_4x4(0, 3);
    ego_agent_past[base_idx + EGO_AGENT_PAST_IDX_Y] = pose_ego_4x4(1, 3);
    ego_agent_past[base_idx + EGO_AGENT_PAST_IDX_COS] = cos_yaw;
    ego_agent_past[base_idx + EGO_AGENT_PAST_IDX_SIN] = sin_yaw;
  };

  if (!reference_time.has_value()) {
    // Legacy behavior: use the last num_timesteps odom messages directly
    const size_t start_idx =
      (odom_msgs.size() >= num_timesteps) ? odom_msgs.size() - num_timesteps : 0;
    for (size_t i = start_idx; i < odom_msgs.size(); ++i) {
      store_pose(i - start_idx, odom_msgs[i].pose.pose);
    }
    return ego_agent_past;
  }

  // Time-based interpolation behavior
  auto stamp_to_sec = [](const builtin_interfaces::msg::Time & stamp) -> double {
    return static_cast<double>(stamp.sec) + static_cast<double>(stamp.nanosec) * 1e-9;
  };

  const double ref_sec = reference_time->seconds();
  constexpr double dt = constants::PREDICTION_TIME_STEP_S;  // 0.1s

  const double first_sec = stamp_to_sec(odom_msgs.front().header.stamp);
  const double last_sec = stamp_to_sec(odom_msgs.back().header.stamp);

  // Both target_sec and odom timestamps are monotonically increasing,
  // so we can carry the search index forward across iterations.
  size_t search_start = 0;

  for (size_t t = 0; t < num_timesteps; ++t) {
    // t=0 is the oldest, t=num_timesteps-1 is the reference time
    const double target_sec = ref_sec - static_cast<double>(num_timesteps - 1 - t) * dt;

    geometry_msgs::msg::Pose interpolated_pose;
    if (target_sec <= first_sec) {
      interpolated_pose = odom_msgs.front().pose.pose;
    } else if (target_sec >= last_sec) {
      interpolated_pose = odom_msgs.back().pose.pose;
    } else {
      // Find the two bracketing odom messages, continuing from previous position
      for (; search_start + 1 < odom_msgs.size(); ++search_start) {
        const double t_next = stamp_to_sec(odom_msgs[search_start + 1].header.stamp);
        if (target_sec <= t_next) {
          break;
        }
      }

      const double t0 = stamp_to_sec(odom_msgs[search_start].header.stamp);
      const double t1 = stamp_to_sec(odom_msgs[search_start + 1].header.stamp);
      const double ratio = (t1 > t0) ? (target_sec - t0) / (t1 - t0) : 0.0;

      interpolated_pose = autoware_utils_geometry::calc_interpolated_pose(
        odom_msgs[search_start].pose.pose, odom_msgs[search_start + 1].pose.pose, ratio, false);
    }

    store_pose(t, interpolated_pose);
  }

  return ego_agent_past;
}

Eigen::Matrix4d pose_to_matrix4d(const geometry_msgs::msg::Pose & pose)
{
  // Extract position
  double x = pose.position.x;
  double y = pose.position.y;
  double z = pose.position.z;

  // Rotation matrix (3x3)
  Eigen::Matrix3d R = quaternion_to_matrix(pose.orientation);

  // Translation vector
  Eigen::Vector3d t(x, y, z);

  // Create 4x4 transformation matrix
  Eigen::Matrix4d pose_matrix = Eigen::Matrix4d::Identity();
  pose_matrix.block<3, 3>(0, 0) = R;
  pose_matrix.block<3, 1>(0, 3) = t;

  return pose_matrix;
}

Eigen::Matrix3d quaternion_to_matrix(const geometry_msgs::msg::Quaternion & q_msg)
{
  const double norm =
    std::sqrt(square(q_msg.w) + square(q_msg.x) + square(q_msg.y) + square(q_msg.z));
  constexpr double kEpsilon = 1e-6;
  if (norm < kEpsilon) {
    throw std::runtime_error("Quaternion norm is too small");
  }

  return Eigen::Quaterniond(q_msg.w, q_msg.x, q_msg.y, q_msg.z).toRotationMatrix();
}

std::pair<float, float> rotation_matrix_to_cos_sin(const Eigen::Matrix3d & rotation_matrix)
{
  // Extract yaw angle from rotation matrix and convert to cos/sin
  // Using atan2 to get the yaw angle from the rotation matrix
  const float yaw = std::atan2(rotation_matrix(1, 0), rotation_matrix(0, 0));
  return {std::cos(yaw), std::sin(yaw)};
}

geometry_msgs::msg::Pose calc_interpolated_pose(
  const Pose1 & src_pose, const Pose2 & dst_pose, const double ratio,
  const bool set_orientation_from_position_direction = true)
{
  const double clamped_ratio = std::clamp(ratio, 0.0, 1.0);

  geometry_msgs::msg::Pose output_pose;
  output_pose.position =
    calc_interpolated_point(get_point(src_pose), get_point(dst_pose), clamped_ratio);

  if (set_orientation_from_position_direction) {
    const double input_poses_dist = calc_distance2d(get_point(src_pose), get_point(dst_pose));
    const bool is_driving_forward_flag = is_driving_forward(src_pose, dst_pose);

    // Get orientation from interpolated point and src_pose
    if ((is_driving_forward_flag && clamped_ratio > 1.0 - (1e-6)) || input_poses_dist < 1e-3) {
      output_pose.orientation = get_pose(dst_pose).orientation;
    } else if (!is_driving_forward_flag && clamped_ratio < 1e-6) {
      output_pose.orientation = get_pose(src_pose).orientation;
    } else {
      const auto & base_pose = is_driving_forward_flag ? dst_pose : src_pose;
      const double pitch = calc_elevation_angle(get_point(output_pose), get_point(base_pose));
      const double yaw = calc_azimuth_angle(get_point(output_pose), get_point(base_pose));
      output_pose.orientation = create_quaternion_from_rpy(0.0, pitch, yaw);
    }
  } else {
    // Get orientation by spherical linear interpolation
    tf2::Transform src_tf;
    tf2::Transform dst_tf;
    tf2::fromMsg(get_pose(src_pose), src_tf);
    tf2::fromMsg(get_pose(dst_pose), dst_tf);
    const auto & quaternion = tf2::slerp(src_tf.getRotation(), dst_tf.getRotation(), clamped_ratio);
    output_pose.orientation = tf2::toMsg(quaternion);
  }

  return output_pose;
}

geometry_msgs::msg::Point calc_interpolated_point(
  const Point1 & src, const Point2 & dst, const double ratio)
{
  const auto src_point = get_point(src);
  const auto dst_point = get_point(dst);

  tf2::Vector3 src_vec;
  src_vec.setX(src_point.x);
  src_vec.setY(src_point.y);
  src_vec.setZ(src_point.z);

  tf2::Vector3 dst_vec;
  dst_vec.setX(dst_point.x);
  dst_vec.setY(dst_point.y);
  dst_vec.setZ(dst_point.z);

  // Get pose by linear interpolation
  const double clamped_ratio = std::clamp(ratio, 0.0, 1.0);
  const auto & vec = tf2::lerp(src_vec, dst_vec, clamped_ratio);

  geometry_msgs::msg::Point point;
  point.x = vec.x();
  point.y = vec.y();
  point.z = vec.z();

  return point;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

bool is_driving_forward(const Pose1 & src_pose, const Pose2 & dst_pose)
{
  // check the first point direction
  const double src_yaw = tf2::getYaw(get_pose(src_pose).orientation);
  const double pose_direction_yaw = calc_azimuth_angle(get_point(src_pose), get_point(dst_pose));
  return std::fabs(normalize_radian(src_yaw - pose_direction_yaw)) < pi / 2.0;
}

geometry_msgs::msg::Pose get_pose([[maybe_unused]] const T & p)
{
  static_assert(sizeof(T) == 0, "Only specializations of get_pose can be used.");
  throw std::logic_error("Only specializations of get_pose can be used.");
}

double calc_azimuth_angle(
  const geometry_msgs::msg::Point & p_from, const geometry_msgs::msg::Point & p_to)
{
  const double dx = p_to.x - p_from.x;
  const double dy = p_to.y - p_from.y;
  return std::atan2(dy, dx);
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

LaneSegmentContext::create_tensor_data_from_indices(
  const Eigen::Matrix4d & transform_matrix,
  const std::map<lanelet::Id, TrafficSignalStamped> & traffic_light_id_map,
  const std::vector<int64_t> & segment_indices, const int64_t max_segments) const
{
  const auto total_points = max_segments * POINTS_PER_SEGMENT;
  Eigen::MatrixXd output_matrix(SEGMENT_POINT_DIM, total_points);
  output_matrix.setZero();

  std::vector<float> speed_limit_vector(max_segments, 0.0f);

  auto convert_to_vector4d = [](const LanePoint & point) {
    return Eigen::Vector4d(point.x(), point.y(), point.z(), 1.0);
  };

  auto encode = [](const int64_t line_type) {
    Eigen::Vector<double, LINE_TYPE_NUM> one_hot = Eigen::Vector<double, LINE_TYPE_NUM>::Zero();
    if (line_type >= 0 && line_type < LINE_TYPE_NUM) {
      one_hot[line_type] = 1.0;
    }
    return one_hot;
  };

  int64_t added_segments = 0;
  for (const int64_t segment_idx : segment_indices) {
    if (added_segments >= max_segments) {
      break;
    }

    const LaneSegment & lane_segment = lanelet_map_.lane_segments[segment_idx];

    // Check if segment has valid data
    if (
      lane_segment.centerline.empty() || lane_segment.left_boundary.empty() ||
      lane_segment.right_boundary.empty()) {
      continue;
    }

    const std::vector<LanePoint> & centerline = lane_segment.centerline;
    const std::vector<LanePoint> & left_boundary = lane_segment.left_boundary;
    const std::vector<LanePoint> & right_boundary = lane_segment.right_boundary;

    if (
      centerline.size() != POINTS_PER_SEGMENT || left_boundary.size() != POINTS_PER_SEGMENT ||
      right_boundary.size() != POINTS_PER_SEGMENT) {
      continue;
    }

    const Eigen::Vector<double, TRAFFIC_LIGHT_ONE_HOT_DIM> traffic_light_one_hot_encoding = [&]() {
      Eigen::Vector<double, TRAFFIC_LIGHT_ONE_HOT_DIM> encoding =
        Eigen::Vector<double, TRAFFIC_LIGHT_ONE_HOT_DIM>::Zero();
      if (lane_segment.traffic_light_id == LaneSegment::TRAFFIC_LIGHT_ID_NONE) {
        encoding[TRAFFIC_LIGHT_NO_TRAFFIC_LIGHT - TRAFFIC_LIGHT] = 1.0;
        return encoding;
      }

      const auto traffic_light_stamped_info_itr =
        traffic_light_id_map.find(lane_segment.traffic_light_id);
      if (traffic_light_stamped_info_itr == traffic_light_id_map.end()) {
        encoding[TRAFFIC_LIGHT_WHITE - TRAFFIC_LIGHT] = 1.0;
        return encoding;
      }

      const auto & signal = traffic_light_stamped_info_itr->second.signal;
      const uint8_t traffic_color =
        identify_current_light_status(lane_segment.turn_direction, signal.elements);
      return Eigen::Vector<double, TRAFFIC_LIGHT_ONE_HOT_DIM>{
        traffic_color == TrafficLightElement::GREEN,    // 3
        traffic_color == TrafficLightElement::AMBER,    // 2
        traffic_color == TrafficLightElement::RED,      // 1
        traffic_color == TrafficLightElement::UNKNOWN,  // 0
        traffic_color == TrafficLightElement::WHITE     // 4
      };
    }();

    const Eigen::Vector<double, LINE_TYPE_NUM> lt_left = encode(lane_segment.left_line_type);
    const Eigen::Vector<double, LINE_TYPE_NUM> lt_right = encode(lane_segment.right_line_type);

    // Process each point in the segment
    for (int64_t i = 0; i < POINTS_PER_SEGMENT; ++i) {
      const int64_t col_idx = added_segments * POINTS_PER_SEGMENT + i;

      // Center (0, 1)
      const Eigen::Vector4d center = transform_matrix * convert_to_vector4d(centerline[i]);
      output_matrix(X, col_idx) = center.x();
      output_matrix(Y, col_idx) = center.y();

      // Direction (2, 3)
      if (i > 0) {
        const int64_t col_idx_p = added_segments * POINTS_PER_SEGMENT + (i - 1);
        output_matrix(dX, col_idx_p) = output_matrix(X, col_idx) - output_matrix(X, col_idx_p);
        output_matrix(dY, col_idx_p) = output_matrix(Y, col_idx) - output_matrix(Y, col_idx_p);
      }

      // Left (4, 5)
      const Eigen::Vector4d left = transform_matrix * convert_to_vector4d(left_boundary[i]);
      output_matrix(LB_X, col_idx) = left.x() - center.x();
      output_matrix(LB_Y, col_idx) = left.y() - center.y();

      // Right (6, 7)
      const Eigen::Vector4d right = transform_matrix * convert_to_vector4d(right_boundary[i]);
      output_matrix(RB_X, col_idx) = right.x() - center.x();
      output_matrix(RB_Y, col_idx) = right.y() - center.y();

      // Traffic Light (8-13)
      output_matrix.block<TRAFFIC_LIGHT_ONE_HOT_DIM, 1>(TRAFFIC_LIGHT, col_idx) =
        traffic_light_one_hot_encoding;

      // Left LineType (14-23)
      output_matrix.block<LINE_TYPE_NUM, 1>(LINE_TYPE_LEFT_START, col_idx) = lt_left;

      // Right LineType (24-33)
      output_matrix.block<LINE_TYPE_NUM, 1>(LINE_TYPE_RIGHT_START, col_idx) = lt_right;
    }

    speed_limit_vector[added_segments] = lane_segment.speed_limit_mps.value_or(0.0f);
    ++added_segments;
  }

  // Convert to float vector
  const Eigen::MatrixXf output_matrix_f = output_matrix.cast<float>().eval();
  std::vector<float> tensor_data(
    output_matrix_f.data(), output_matrix_f.data() + output_matrix_f.size());

  return {tensor_data, speed_limit_vector};
}

uint8_t identify_current_light_status(
  const int64_t turn_direction, const std::vector<TrafficLightElement> & traffic_light_elements)
{
  // Filter out ineffective elements (color == 0 which is UNKNOWN)
  std::vector<TrafficLightElement> effective_elements;
  for (const auto & element : traffic_light_elements) {
    if (element.color != TrafficLightElement::UNKNOWN) {
      effective_elements.push_back(element);
    }
  }

  // If no effective elements, return UNKNOWN (0)
  if (effective_elements.empty()) {
    return TrafficLightElement::UNKNOWN;
  }

  // If only one effective element, return its color
  if (effective_elements.size() == 1) {
    return effective_elements[0].color;
  }

  // For multiple elements, find the one that matches the turn direction
  // Map turn direction to corresponding arrow shape
  const std::map<int64_t, uint8_t> direction_to_shape_map = {
    {LaneSegment::TURN_DIRECTION_NONE, TrafficLightElement::UNKNOWN},       // none
    {LaneSegment::TURN_DIRECTION_STRAIGHT, TrafficLightElement::UP_ARROW},  // straight
    {LaneSegment::TURN_DIRECTION_LEFT, TrafficLightElement::LEFT_ARROW},    // left
    {LaneSegment::TURN_DIRECTION_RIGHT, TrafficLightElement::RIGHT_ARROW}   // right
  };

  const auto target_shape_iter = direction_to_shape_map.find(turn_direction);
  const uint8_t target_shape = (target_shape_iter != direction_to_shape_map.end())
                                 ? target_shape_iter->second
                                 : TrafficLightElement::UNKNOWN;

  // If multiple matching elements, take the one with highest confidence
  auto get_max_confidence_color = [](const std::vector<TrafficLightElement> & elements) {
    return std::max_element(
             elements.begin(), elements.end(),
             [](const TrafficLightElement & a, const TrafficLightElement & b) {
               return a.confidence < b.confidence;
             })
      ->color;
  };

  // First priority: Find elements with exactly matching direction
  std::vector<TrafficLightElement> matching_elements;
  for (const TrafficLightElement & element : effective_elements) {
    if (element.shape == target_shape) {
      matching_elements.push_back(element);
    }
  }
  if (!matching_elements.empty()) {
    return get_max_confidence_color(matching_elements);
  }

  // Second priority: Find circle elements
  std::vector<TrafficLightElement> circle_elements;
  for (const TrafficLightElement & element : effective_elements) {
    if (element.shape == TrafficLightElement::CIRCLE) {
      circle_elements.push_back(element);
    }
  }
  if (!circle_elements.empty()) {
    return get_max_confidence_color(circle_elements);
  }

  // If no matching direction or circle, return the element with highest confidence
  return get_max_confidence_color(effective_elements);
}

std::vector<float> replicate_for_batch(const std::vector<float> & single_data, const int batch_size)
{
  const size_t single_size = single_data.size();
  const size_t total_size = static_cast<size_t>(batch_size) * single_size;

  std::vector<float> batch_data;
  batch_data.reserve(total_size);

  for (int i = 0; i < batch_size; ++i) {
    batch_data.insert(batch_data.end(), single_data.begin(), single_data.end());
  }

  return batch_data;
}

void normalize_input_data(InputDataMap & input_data_map, const NormalizationMap & normalization_map)
{
  auto normalize_vector = [](
                            std::vector<float> & data, const std::vector<float> & mean,
                            const std::vector<float> & std_dev) -> void {
    assert(!data.empty() && "Data vector must not be empty");
    assert((mean.size() == std_dev.size()) && "Mean and std must be same size");
    assert((data.size() % std_dev.size() == 0) && "Data size must be divisible by std_dev size");
    auto cols = std_dev.size();
    auto rows = data.size() / cols;

    for (size_t row = 0; row < rows; ++row) {
      const auto offset = row * cols;
      const auto row_begin =
        data.begin() + static_cast<std::vector<float>::difference_type>(offset);

      bool is_zero_row = std::all_of(
        row_begin, row_begin + static_cast<std::vector<float>::difference_type>(cols),
        [](float x) { return std::abs(x) < std::numeric_limits<float>::epsilon(); });

      if (is_zero_row) continue;

      for (size_t col = 0; col < cols; ++col) {
        float m = (mean.size() == 1) ? mean[0] : mean[col];
        float s = (std_dev.size() == 1) ? std_dev[0] : std_dev[col];
        // Prevent division by zero
        if (std::abs(s) < std::numeric_limits<float>::epsilon()) {
          throw std::runtime_error("Standard deviation is zero, cannot normalize data");
        }
        data[offset + col] = (data[offset + col] - m) / s;
      }
    }
  };

  for (auto & [key, value] : input_data_map) {
    // Skip normalization for ego_shape, sampled_trajectories, turn_indicators, and delay
    if (
      key == "ego_shape" || key == "sampled_trajectories" || key == "turn_indicators" ||
      key == "delay") {
      continue;
    }

    if (normalization_map.find(key) == normalization_map.end()) {
      std::string err{"Missing key " + key + " from normalization map"};
      throw std::runtime_error(err.c_str());
    }

    const auto & [mean, std_dev] = normalization_map.at(key);
    normalize_vector(value, mean, std_dev);
  }
}

TensorrtInference::InferenceResult DiffusionPlannerCore::run_inference(
  const InputDataMap & input_data_map)
{
  if (!tensorrt_inference_) {
    TensorrtInference::InferenceResult result;
    result.error_msg = "Model not loaded";
    return result;
  }
  return tensorrt_inference_->infer(input_data_map);
}

TensorrtInference::InferenceResult TensorrtInference::infer(
  const preprocess::InputDataMap & input_data_map)
{
  transferInputsToDevice(input_data_map);

  const bool status = network_trt_ptr_->enqueueV3(stream_);
  CHECK_CUDA_ERROR(cudaStreamSynchronize(stream_));

  if (!status) {
    InferenceResult result;
    result.error_msg = "Failed to enqueue and do inference.";
    return result;
  }

  // Async D2H via pre-allocated pinned host buffers
  CHECK_CUDA_ERROR(cudaMemcpyAsync(
    output_pinned_.get(), output_d_.get(), output_num_elements_ * sizeof(float),
    cudaMemcpyDeviceToHost, stream_));
  CHECK_CUDA_ERROR(cudaMemcpyAsync(
    logit_pinned_.get(), turn_indicator_logit_d_.get(), logit_num_elements_ * sizeof(float),
    cudaMemcpyDeviceToHost, stream_));
  CHECK_CUDA_ERROR(cudaStreamSynchronize(stream_));

  std::vector<float> output_host(output_pinned_.get(), output_pinned_.get() + output_num_elements_);
  std::vector<float> logit_host(logit_pinned_.get(), logit_pinned_.get() + logit_num_elements_);

  InferenceResult result;
  result.outputs = std::make_pair(std::move(output_host), std::move(logit_host));
  return result;
}

void TensorrtInference::transferInputsToDevice(const preprocess::InputDataMap & input_data_map)
{
  // Helper lambda for async H2D of float tensors
  const auto h2d = [this](const auto & host_vec, const auto & device_ptr) {
    CHECK_CUDA_ERROR(cudaMemcpyAsync(
      device_ptr.get(), host_vec.data(), host_vec.size() * sizeof(float), cudaMemcpyHostToDevice,
      stream_));
  };

  h2d(input_data_map.at("sampled_trajectories"), sampled_trajectories_d_);
  h2d(input_data_map.at("ego_agent_past"), ego_history_d_);
  h2d(input_data_map.at("ego_current_state"), ego_current_state_d_);
  h2d(input_data_map.at("neighbor_agents_past"), neighbor_agents_past_d_);
  h2d(input_data_map.at("static_objects"), static_objects_d_);
  h2d(input_data_map.at("lanes"), lanes_d_);
  h2d(input_data_map.at("lanes_speed_limit"), lanes_speed_limit_d_);
  h2d(input_data_map.at("route_lanes"), route_lanes_d_);
  h2d(input_data_map.at("route_lanes_speed_limit"), route_lanes_speed_limit_d_);
  h2d(input_data_map.at("polygons"), polygons_d_);
  h2d(input_data_map.at("line_strings"), line_strings_d_);
  h2d(input_data_map.at("goal_pose"), goal_pose_d_);
  h2d(input_data_map.at("ego_shape"), ego_shape_d_);
  h2d(input_data_map.at("turn_indicators"), turn_indicators_d_);
  h2d(input_data_map.at("delay"), delay_d_);

  // CPU-side float→bool conversion for speed limit masks
  const auto convert_speed_mask =
    [this](const std::vector<float> & speed_limit, const auto & device_ptr, size_t count) {
      std::vector<uint8_t> bool_array(count);
      for (size_t i = 0; i < count; ++i) {
        bool_array[i] = speed_limit[i] > std::numeric_limits<float>::epsilon();
      }
      CHECK_CUDA_ERROR(cudaMemcpyAsync(
        device_ptr.get(), bool_array.data(), count * sizeof(uint8_t), cudaMemcpyHostToDevice,
        stream_));
    };

  convert_speed_mask(
    input_data_map.at("lanes_speed_limit"), lanes_has_speed_limit_d_,
    batch_size_ * num_elements(LANES_SPEED_LIMIT_SHAPE));
  convert_speed_mask(
    input_data_map.at("route_lanes_speed_limit"), route_lanes_has_speed_limit_d_,
    batch_size_ * num_elements(ROUTE_LANES_SPEED_LIMIT_SHAPE));
}

bool TrtCommon::enqueueV3(cudaStream_t stream)
{
  if (!context_) {
    logger_->log(nvinfer1::ILogger::Severity::kERROR, "Context is not initialized");
    return false;
  }
  if (trt_config_->profile_per_layer) {
    auto inference_start = std::chrono::high_resolution_clock::now();
    auto success = context_->enqueueV3(stream);
    auto inference_end = std::chrono::high_resolution_clock::now();
    host_profiler_->reportLayerTime(
      "inference_host",
      std::chrono::duration<float, std::milli>(inference_end - inference_start).count());
    return success;
  }
  return context_->enqueueV3(stream);
}

bool enqueueV3(cudaStream_t stream) noexcept
{
    return mImpl->enqueueV3(stream);
}
